    n = len(grid[0])
    c = n // 2
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= c:
            out[r][c-r] = 2
            out[r][c+r] = 2
            if r == c and c % 2 == 1:
                for j in range(n):
                    if j % 4 == (r+c) % 4 and out[r][j] == 0:
                        out[r][j] = 1
        else:
            for j in range(n):
                if j % 4 == (r+c) % 4:
                    out[r][j] = 1
    return out
'''
